using Polly;
using Polly.Retry;
using Polly.CircuitBreaker;
using Polly.Bulkhead;

// Create resilience pipeline
var retryPolicy = Policy
    .Handle<HttpRequestException>()
    .OrResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
    .WaitAndRetryAsync(
        retryCount: 3,
        sleepDurationProvider: retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)),
        onRetry: (outcome, timeSpan, retryCount, context) =>
        {
            Console.WriteLine($"Retry {retryCount} after {timeSpan.TotalSeconds}s due to: {outcome.Exception?.Message}");
        });

var circuitBreakerPolicy = Policy
    .Handle<HttpRequestException>()
    .CircuitBreakerAsync(
        exceptionsAllowedBeforeBreaking: 5,
        durationOfBreak: TimeSpan.FromSeconds(30),
        onBreak: (ex, breakDelay) => Console.WriteLine($"Circuit broken for {breakDelay.TotalSeconds}s"),
        onReset: () => Console.WriteLine("Circuit reset"));

var bulkheadPolicy = Policy.BulkheadAsync(
    maxParallelization: 10,
    maxQueuingActions: 5,
    onBulkheadRejected: (context) => Console.WriteLine("Bulkhead rejected"));

var resiliencePipeline = Policy.WrapAsync(
    circuitBreakerPolicy,
    retryPolicy,
    bulkheadPolicy);

// Use with AI client
public class ResilientAIClient
{
    private readonly HttpClient _httpClient;
    private readonly AsyncPolicy<HttpResponseMessage> _pipeline;

    public ResilientAIClient(HttpClient httpClient, AsyncPolicy<HttpResponseMessage> pipeline)
    {
        _httpClient = httpClient;
        _pipeline = pipeline;
    }

    public async Task<string> CompleteAsync(string prompt)
    {
        return await _pipeline.ExecuteAsync(async () =>
        {
            var response = await _httpClient.PostAsJsonAsync("/completions", new { prompt });
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        });
    }
}
